1950  template <> otError NcpBase::HandlePropertySet<SPINEL_PROP_STREAM_NET>(void)
  1951  {
  1952      const uint8_t *framePtr = NULL;
  1953      uint16_t       frameLen = 0;
  1954      const uint8_t *metaPtr  = NULL;
  1955      uint16_t       metaLen  = 0;
  1956      otMessage *    message  = NULL;
  1957      otError        error    = OT_ERROR_NONE;
  1958
  1959      SuccessOrExit(error = mDecoder.ReadDataWithLen(framePtr, frameLen));
  1960      SuccessOrExit(error = mDecoder.ReadData(metaPtr, metaLen));
  1961
  1962      // We ignore metadata for now.
  1963      // May later include TX power, allow retransmits, etc...
  1964
  1965      // STREAM_NET requires layer 2 security.
  1966      message = otIp6NewMessageFromBuffer(mInstance, framePtr, frameLen, NULL);
  1967      VerifyOrExit(message != NULL, error = OT_ERROR_NO_BUFS);
  1968
  1969      error = otIp6Send(mInstance, message);
  1970
  1971      // `otIp6Send()` takes ownership of `message` (in both success or
  1972      // failure cases). `message` is set to NULL so it is not freed at
  1973      // exit.
  1974      message = NULL;
  1975
  1976  exit:
  1977
  1978      if (message != NULL)
  1979      {
  1980          otMessageFree(message);
  1981      }
  1982
  1983      if (error == OT_ERROR_NONE)
  1984      {
  1985          mInboundSecureIpFrameCounter++;
  1986      }
  1987      else
  1988      {
  1989          mDroppedInboundIpFrameCounter++;
  1990      }
  1991
  1992      return error;
  1993  }
